import { useState, FormEvent } from 'react';
import {
  JxInputField,
  JxSelect,
  JxSwitch,
  JxButton,
  JxAlert,
} from '@jinx-ui/react';

const roleOptions = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function InviteTeamForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const emailTouched = email.length > 0;
  const emailValid = emailPattern.test(email);
  const emailError = emailTouched && !emailValid ? 'Укажите адрес в формате name@example.com' : undefined;

  const canSubmit = emailValid;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!canSubmit) return;
    setSubmitted(true);
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r)',
        maxWidth: 360,
      }}
    >
      {submitted && (
        <JxAlert intent="success" title="Приглашение отправлено">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 'var(--jx-r)' }}>
            <span>Приглашение для {email} создано.</span>
            <JxButton
              variant="ghost"
              size="sm"
              type="button"
              aria-label="Закрыть сообщение"
              onClick={() => setSubmitted(false)}
            >
              Закрыть
            </JxButton>
          </div>
        </JxAlert>
      )}

      <form
        onSubmit={handleSubmit}
        style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-lg)' }}
      >
        <JxInputField
          label="Электронная почта"
          type="email"
          required
          placeholder="name@example.com"
          helperText="Мы отправим приглашение на этот адрес"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          errorText={emailError}
        />

        <JxSelect
          label="Роль"
          options={roleOptions}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление о приглашении"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <JxButton type="submit" variant="primary" disabled={!canSubmit}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

